import { useEffect, useRef, useState } from 'react';
import { freshBoardCode } from '../session/fresh-board.ts';
import { Bracket } from './Bracket.tsx';
import { Confirm } from './Confirm.tsx';
import { exportTournament, importTournament } from './format.ts';
import {
  finishTurn,
  nameError,
  newTournament,
  normalizeName,
  roundName,
  roundSize,
} from './rules.ts';
import { readHistory, saveHistory } from './storage.ts';
import { Turn } from './Turn.tsx';
import type { Result, Tournament as Event } from './rules.ts';
import './tournament.css';

export function Tournament({ back }: { back(): void }) {
  const [count, setCount] = useState(4);
  const [names, setNames] = useState(Array<string>(8).fill(''));
  const [event, setEvent] = useState<Event | null>(null);
  const [history, setHistory] = useState(readHistory);
  const [draft, setDraft] = useState('');
  const [notice, setNotice] = useState('');
  const [announcement, setAnnouncement] = useState(0);
  const [pending, setPending] = useState<(() => void) | null>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const snapshot = useRef<(() => string) | null>(null);
  useEffect(() => {
    heading.current?.focus();
  }, []);
  function publish(text: string) {
    setNotice(text);
    setAnnouncement((n) => n + 1);
  }
  function orient() {
    requestAnimationFrame(() => heading.current?.focus());
  }
  function replace(action: () => void) {
    if (event && event.phase !== 'champion') setPending(() => action);
    else action();
  }
  function start() {
    const accepted = names.slice(0, count).map(normalizeName);
    const error = nameError(accepted);
    if (error) {
      publish(error);
      return;
    }
    const codes: string[] = [];
    for (let i = 0; i < count - 1; i++) {
      let code: string;
      do {
        code = freshBoardCode(roundSize(count, i));
      } while (codes.includes(code));
      codes.push(code);
    }
    setEvent(newTournament(accepted, codes));
    publish(`Now playing: ${accepted[0]}`);
    orient();
  }
  function turnFinished(result: Result) {
    setEvent((current) => (current ? finishTurn(current, result) : current));
  }
  function nextMatch() {
    if (!event) return;
    if (event.current === event.matches.length - 1) {
      const champion: Event = { ...event, phase: 'champion' };
      const items = [champion, ...history.items].slice(0, 10);
      setHistory({ items, blocked: !saveHistory(items) });
      setEvent(champion);
      publish(`Champion: ${champion.names[champion.matches[champion.current]!.winner!]}`);
    } else {
      const next = { ...event, current: event.current + 1, phase: 'ready' as const };
      setEvent(next);
      publish(`Now playing: ${next.names[next.matches[next.current]!.players[0]!]}`);
    }
    orient();
  }
  function load() {
    const parsed = importTournament(draft);
    if (parsed.error) {
      publish(parsed.error);
      return;
    }
    replace(() => {
      setEvent(parsed.tournament);
      publish('Tournament loaded.');
      orient();
    });
  }
  const match = event?.matches[event.current];
  const player = match
    ? match.players[
        match.results[0] && (event?.phase === 'ready' || event?.phase === 'playing') ? 1 : 0
      ]
    : null;
  return (
    <main className="tournament">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 tabIndex={-1} ref={heading}>
        Tournament
      </h2>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={announcement}>{notice}</span>
        </p>
      </div>
      {!event ? (
        <>
          <label>
            Players{' '}
            <select
              className="control"
              value={count}
              onChange={(e) => setCount(Number(e.currentTarget.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
          </label>
          <div className="tournament-fields">
            {names.slice(0, count).map((name, index) => (
              <label key={index}>
                Player {index + 1}
                <input
                  className="control"
                  value={name}
                  onChange={(e) => {
                    const next = e.currentTarget.value;
                    setNames(names.map((value, i) => (i === index ? next : value)));
                  }}
                />
              </label>
            ))}
          </div>
          <div className="tournament-actions">
            <button className="control" onClick={start}>
              Start tournament
            </button>
            <button className="control" onClick={back}>
              Back to game
            </button>
          </div>
          <h3>Past tournaments</h3>
          {history.blocked && <p>Progress won't be saved on this device.</p>}
          {history.items.length === 0 ? (
            <p>No past tournaments yet.</p>
          ) : (
            <ul>
              {history.items.map((item, index) => (
                <li key={index}>
                  <button
                    className="control"
                    onClick={() => {
                      setEvent(item);
                      publish('Tournament loaded.');
                      orient();
                    }}
                  >
                    Champion: {item.names[item.matches[item.current]!.winner!]}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </>
      ) : (
        <>
          {event.phase === 'champion' ? (
            <>
              <h3>Champion: {event.names[match!.winner!]}</h3>
              <button className="control" onClick={back}>
                Back to game
              </button>
            </>
          ) : (
            <>
              <p>Round: {roundName(event.names.length, event.current)}</p>
              {(event.phase === 'ready' || event.phase === 'playing') && (
                <p>Now playing: {event.names[player!]}</p>
              )}
              {event.phase === 'ready' && (
                <button
                  className="control"
                  onClick={() => {
                    setEvent({ ...event, phase: 'playing' });
                    publish(`Now playing: ${event.names[player!]}`);
                    orient();
                  }}
                >
                  Start turn
                </button>
              )}
              {event.phase === 'playing' && (
                <Turn
                  key={`${event.current}-${match!.results[0] ? 1 : 0}`}
                  code={match!.code}
                  snapshot={event.snapshot}
                  finish={turnFinished}
                  capture={(fn) => {
                    snapshot.current = fn;
                  }}
                  announce={publish}
                />
              )}
              {event.phase === 'turn-ended' && (
                <button
                  className="control"
                  onClick={() => {
                    setEvent({ ...event, phase: 'ready' });
                    publish(`Now playing: ${event.names[match!.players[1]!]}`);
                    orient();
                  }}
                >
                  Next turn
                </button>
              )}
              {event.phase === 'match-ended' && (
                <button className="control" onClick={nextMatch}>
                  Next match
                </button>
              )}
              <button className="control" onClick={() => replace(back)}>
                Leave tournament
              </button>
            </>
          )}
          <Bracket tournament={event} />
        </>
      )}
      <label className="tournament-json">
        Tournament JSON
        <textarea
          className="control"
          value={draft}
          onChange={(e) => setDraft(e.currentTarget.value)}
        />
      </label>
      <div className="tournament-actions">
        <button
          className="control"
          onClick={() => {
            setDraft(
              exportTournament(
                event?.phase === 'playing'
                  ? { ...event, snapshot: snapshot.current?.() ?? null }
                  : event,
              ),
            );
          }}
        >
          Export tournament
        </button>
        <button className="control" onClick={load}>
          Load tournament
        </button>
      </div>
      {pending && (
        <Confirm
          cancel={() => setPending(null)}
          leave={() => {
            const action = pending;
            setPending(null);
            action();
          }}
        />
      )}
    </main>
  );
}

